"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * LIVE LINE CHART: one metric as it happens
 *
 *   stream    each new point slides in from the right over the
 *             time it took to arrive, so the line moves at an
 *             even pace instead of jumping a step at a time; the
 *             end dot rides the line and pings
 *   scale     when the range changes the line rescales smoothly
 *             under fixed gridlines and the axis figures roll
 *   point     point at the line and the header becomes the
 *             readout: the figure rolls to that moment and
 *             "now" morphs to how long ago it was
 *   pause     the Live pill holds the view still while data
 *             keeps coming; press again to catch up
 *   waiting   when points stop coming the pill says so and its
 *             pulse stops
 *   limit     an optional threshold is drawn as a dashed line
 *             with its label riding the scale
 *
 * The line is drawn in value space inside one scaled group, so
 * a new range is a single transform transition; the slide is a
 * second transform on the group around it. No chart library,
 * no frame loop.
 * ───────────────────────────────────────────────────────── */

export interface LivePoint {
  /** When, in ms (e.g. Date.now() when it was measured). */
  t: number;
  value: number;
}

export interface LiveLineChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  /** Points oldest first; keep appending. Anything older than the window is left out. */
  data: LivePoint[];
  /** How much time the chart shows, in ms. */
  window?: number;
  /** Over the figure, e.g. "Requests". */
  label?: React.ReactNode;
  /** After the figure, e.g. "req/s". */
  unit?: string;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  /** A limit drawn as a dashed line, e.g. { value: 1200, label: "Rate limit" }. */
  threshold?: { value: number; label?: string };
  color?: string;
  /** Plot height in px. */
  height?: number;
  defaultPaused?: boolean;
  onPausedChange?: (paused: boolean) => void;
  /** Ms without a new point before the pill says Waiting; defaults to three times the last gap. */
  staleAfter?: number;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const AXIS = 44;
const COMPACT: Intl.NumberFormatOptions = {
  notation: "compact",
  maximumFractionDigits: 1,
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** A round step near x: 1, 2, 2.5 or 5 times a power of ten. */
function nice(x: number) {
  if (x <= 0 || !Number.isFinite(x)) return 1;
  const p = 10 ** Math.floor(Math.log10(x));
  const f = x / p;
  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p;
}

/** Three round gridlines that hold every value in view, with room above and below. */
function scaleFor(values: number[], extra?: number) {
  const all = extra === undefined ? values : [...values, extra];
  if (!all.length) return { lo: 0, hi: 1 };
  let lo = Math.min(...all);
  let hi = Math.max(...all);
  const pad = (hi - lo) * 0.15 || Math.abs(hi) * 0.1 || 1;
  const step = nice((hi - lo + pad * 2) / 2);
  lo = Math.floor((lo - pad) / step) * step;
  hi = Math.ceil((hi + pad) / step) * step;
  if (Math.min(...all) >= 0) lo = Math.max(0, lo);
  return { lo, hi: hi > lo ? hi : lo + step };
}

export function LiveLineChart({
  data,
  window: span = 60_000,
  label,
  unit,
  format = { maximumFractionDigits: 0 },
  locales,
  threshold,
  color = "var(--chart-1, var(--primary))",
  height = 140,
  defaultPaused = false,
  onPausedChange,
  staleAfter,
  className = "",
  ...props
}: LiveLineChartProps) {
  const reduced = useReducedMotion();
  const gradient = React.useId().replace(/:/g, "");
  const plotRef = React.useRef<HTMLDivElement>(null);
  const slideRef = React.useRef<SVGGElement>(null);
  const previous = React.useRef<number | null>(null);
  const plotLeft = React.useRef(0);
  const [width, setWidth] = React.useState(0);
  const [frozen, setFrozen] = React.useState<LivePoint[] | null>(
    defaultPaused ? data : null,
  );
  const [staleFor, setStaleFor] = React.useState<number | null>(null);
  const [hover, setHover] = React.useState<number | null>(null);

  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      const w = Math.floor(entry.contentRect.width);
      setWidth((prev) => (prev === w ? prev : w));
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const paused = frozen !== null;
  const view = frozen ?? data;
  const latest = view[view.length - 1];
  const before = view[view.length - 2];
  const gap = latest && before ? latest.t - before.t : 1000;
  const plotW = Math.max(0, width - AXIS);
  const k = plotW / span;

  // The points in view, plus the one before the window so the line reaches the left edge.
  const firstIn = latest ? view.findIndex((p) => p.t >= latest.t - span) : 0;
  const shown = latest ? view.slice(Math.max(0, firstIn - 1)) : [];
  const { lo, hi } = scaleFor(
    shown.map((p) => p.value),
    threshold?.value,
  );
  const range = hi - lo;
  const yOf = (v: number) => height - ((v - lo) / range) * height;
  const xOf = (t: number) => (latest ? plotW - (latest.t - t) * k : 0);

  const line = shown
    .map((p, i) => `${i ? "L" : "M"}${xOf(p.t).toFixed(1)} ${p.value}`)
    .join("");
  const area = shown.length
    ? `${line}L${xOf(shown[shown.length - 1].t).toFixed(1)} ${lo}L${xOf(shown[0].t).toFixed(1)} ${lo}Z`
    : "";

  // A new point: start the line one step to the right and slide it into place over the gap it took to arrive.
  React.useLayoutEffect(() => {
    const g = slideRef.current;
    const t = latest?.t ?? null;
    const last = previous.current;
    previous.current = t;
    if (!g || t === null || last === null || t <= last || reduced || !k) return;
    const dt = Math.min(t - last, 4000);
    g.style.transition = "none";
    g.style.transform = `translateX(${(dt * k).toFixed(2)}px)`;
    g.getBoundingClientRect();
    g.style.transition = `transform ${dt}ms linear`;
    g.style.transform = "translateX(0px)";
  }, [latest?.t, reduced, k]);

  // No new point for a while: say so.
  const waitFor = staleAfter ?? Math.max(2000, gap * 3);
  React.useEffect(() => {
    if (!latest || paused) return;
    const at = latest.t;
    const timer = window.setTimeout(() => setStaleFor(at), waitFor);
    return () => window.clearTimeout(timer);
  }, [latest, paused, waitFor]);
  const stale = !paused && latest !== undefined && staleFor === latest.t;

  const togglePause = () => {
    const next = !paused;
    setFrozen(next ? data : null);
    onPausedChange?.(next);
  };

  const onMove = (e: React.PointerEvent) => {
    if (!latest) return;
    // Measured once per visit, not on every move.
    if (!plotLeft.current)
      plotLeft.current = e.currentTarget.getBoundingClientRect().left;
    const x = e.clientX - plotLeft.current - AXIS;
    const t = latest.t - (plotW - x) / (k || 1);
    let best = -1;
    let bestD = Infinity;
    shown.forEach((p, i) => {
      const d = Math.abs(p.t - t);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    const pick = best >= 0 ? shown[best].t : null;
    setHover((prev) => (prev === pick ? prev : pick));
  };

  const pointed =
    hover !== null ? (shown.find((p) => p.t === hover) ?? null) : null;
  const start = shown.find((p) => p.t >= (latest?.t ?? 0) - span) ?? shown[0];
  const change =
    latest && start && start.value
      ? (latest.value - start.value) / Math.abs(start.value)
      : 0;
  const up = change >= 0;
  const ago = pointed && latest ? Math.round((latest.t - pointed.t) / 1000) : 0;
  const caption = pointed ? (ago === 0 ? "now" : `${ago}s ago`) : "now";
  const status = paused ? "Paused" : stale ? "Waiting" : "Live";
  const live = status === "Live";
  const scaleMove = reduced ? "none" : `transform 600ms ${EASE}`;

  return (
    <div
      className={`w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      {/* Its natural width where the parent sizes to its content (a centred flex column), without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 520px)" }}
      />
      <div className="@container w-full">
        <div className="p-4 @md:p-5">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              {label && (
                <p className="text-[12px] text-muted-foreground @md:text-[13px]">
                  {label}
                </p>
              )}
              <p className="mt-0.5 flex items-baseline gap-1.5">
                <span className="text-[26px] font-semibold leading-none tracking-[-0.03em] text-foreground tabular-nums @md:text-[32px]">
                  <NumberRoll
                    value={pointed ? pointed.value : (latest?.value ?? 0)}
                    format={format}
                    locales={locales}
                    duration={500}
                  />
                </span>
                {unit && (
                  <span className="text-[12px] text-muted-foreground @md:text-[13px]">
                    {unit}
                  </span>
                )}
                <span className="ml-1 text-[11.5px] text-muted-foreground @md:text-[12px]">
                  <TextMorph duration={320}>{caption}</TextMorph>
                </span>
              </p>
              <p className="mt-1.5 flex items-center gap-1 text-[11.5px] text-muted-foreground @md:text-[12px]">
                <span
                  className={`inline-flex items-center gap-0.5 font-medium tabular-nums ${up ? "text-emerald-600 dark:text-emerald-400" : "text-red-600 dark:text-red-400"}`}
                >
                  <svg
                    aria-hidden="true"
                    viewBox="0 0 10 10"
                    className="size-2.5"
                    style={{
                      transform: up ? "none" : "rotate(180deg)",
                      transition: reduced ? "none" : `transform 400ms ${EASE}`,
                    }}
                  >
                    <path d="M5 1.5 9 8.5H1z" fill="currentColor" />
                  </svg>
                  <NumberRoll
                    value={Math.abs(change)}
                    format={{ style: "percent", maximumFractionDigits: 1 }}
                    duration={600}
                  />
                </span>
                <span>over the last {Math.round(span / 1000)}s</span>
              </p>
            </div>

            <button
              type="button"
              aria-pressed={paused}
              aria-label={paused ? "Resume live updates" : "Pause live updates"}
              onClick={togglePause}
              className={`flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-full px-2.5 text-[12px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
            >
              <span
                aria-hidden="true"
                className="relative flex size-2 items-center justify-center"
              >
                {live && !reduced && (
                  <span className="absolute inset-0 animate-[ui-ping_1.6s_ease-out_infinite] rounded-full bg-emerald-500" />
                )}
                <span
                  className={`relative size-2 rounded-full transition-colors duration-300 ${live ? "bg-emerald-500" : stale ? "bg-amber-500" : "bg-muted-foreground"}`}
                />
              </span>
              <TextMorph duration={360}>{status}</TextMorph>
            </button>
          </div>

          <div
            ref={plotRef}
            className="relative mt-4 w-full touch-pan-y"
            style={{ height: height + 22 }}
            onPointerMove={onMove}
            onPointerLeave={() => {
              plotLeft.current = 0;
              setHover(null);
            }}
          >
            {/* Axis figures: fixed places, rolling values. */}
            {[hi, (hi + lo) / 2, lo].map((v, i) => (
              <span
                key={i}
                aria-hidden="true"
                className="absolute left-0 -translate-y-1/2 text-[10.5px] text-muted-foreground tabular-nums @md:text-[11px]"
                style={{ top: (height / 2) * i }}
              >
                <NumberRoll
                  value={v}
                  format={COMPACT}
                  locales={locales}
                  duration={600}
                />
              </span>
            ))}

            <svg
              aria-hidden="true"
              width={plotW}
              height={height}
              className="absolute top-0 overflow-hidden"
              style={{ left: AXIS }}
            >
              <defs>
                <linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1">
                  {/* The area is drawn in value space, flipped: offset 0 is the bottom of the plot. */}
                  <stop offset="0%" stopColor={color} stopOpacity="0" />
                  <stop offset="100%" stopColor={color} stopOpacity="0.24" />
                </linearGradient>
              </defs>
              {[0, 0.5, 1].map((f) => (
                <line
                  key={f}
                  x1={0}
                  x2={plotW}
                  y1={f * height}
                  y2={f * height}
                  stroke="var(--border)"
                  strokeWidth={1}
                  shapeRendering="crispEdges"
                />
              ))}
              <g ref={slideRef}>
                {/* Drawn in value space; the range is one transform, so a new range eases instead of jumping. */}
                <g
                  style={{
                    transform: `translateY(${height}px) scaleY(${-height / range}) translateY(${-lo}px)`,
                    transformOrigin: "0 0",
                    transition: scaleMove,
                  }}
                >
                  <path d={area} fill={`url(#${gradient})`} />
                  {threshold && (
                    <line
                      x1={-plotW}
                      x2={plotW * 2}
                      y1={threshold.value}
                      y2={threshold.value}
                      className="stroke-amber-500 dark:stroke-amber-400"
                      strokeWidth={1.5}
                      strokeDasharray="5 4"
                      vectorEffect="non-scaling-stroke"
                    />
                  )}
                  <path
                    d={line}
                    fill="none"
                    stroke={color}
                    strokeWidth={2}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    vectorEffect="non-scaling-stroke"
                  />
                </g>
                {pointed && (
                  <g>
                    <line
                      x1={xOf(pointed.t)}
                      x2={xOf(pointed.t)}
                      y1={0}
                      y2={height}
                      stroke="var(--foreground)"
                      strokeOpacity={0.25}
                      strokeWidth={1}
                    />
                    <circle
                      cx={xOf(pointed.t)}
                      cy={yOf(pointed.value)}
                      r={4}
                      fill="var(--background)"
                      stroke={color}
                      strokeWidth={2}
                    />
                  </g>
                )}
              </g>
            </svg>

            {/* The newest point: a dot that rides the line's right end, pinging while live. */}
            {latest && plotW > 0 && (
              <span
                aria-hidden="true"
                className="absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full"
                style={{
                  left: AXIS + plotW,
                  top: yOf(latest.value),
                  background: color,
                  boxShadow: "0 0 0 2px var(--background)",
                  transition: reduced
                    ? "none"
                    : `top ${Math.min(gap, 4000)}ms linear`,
                }}
              >
                {live && !reduced && (
                  <span
                    className="absolute inset-0 animate-[ui-ping_1.6s_ease-out_infinite] rounded-full"
                    style={{ background: color }}
                  />
                )}
              </span>
            )}

            {threshold && (
              <span
                aria-hidden="true"
                className="absolute right-0 -translate-y-full pb-0.5 text-[10.5px] font-medium text-amber-600 tabular-nums dark:text-amber-400"
                style={{
                  top: yOf(threshold.value),
                  transition: reduced ? "none" : `top 600ms ${EASE}`,
                }}
              >
                {threshold.label ?? "Limit"}
              </span>
            )}

            <div
              aria-hidden="true"
              className="absolute inset-x-0 bottom-0 flex justify-between text-[10.5px] text-muted-foreground @md:text-[11px]"
              style={{ paddingLeft: AXIS }}
            >
              <span>−{Math.round(span / 1000)}s</span>
              <span>−{Math.round(span / 2000)}s</span>
              <span>now</span>
            </div>
          </div>

          <p className="sr-only" aria-live="off">
            {latest
              ? `Latest ${new Intl.NumberFormat(locales ?? "en-US", format).format(latest.value)}${unit ? ` ${unit}` : ""}, ${up ? "up" : "down"} ${Math.round(Math.abs(change) * 1000) / 10}% over the last ${Math.round(span / 1000)} seconds.`
              : "No data yet."}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}
